w in store</h2>\n<!-- /wp:heading -->\n\n<!-- wp:woocommerce/product-new {\"columns\":4,\"rows\":1} /--></div>\n<!-- /wp:woocommerce/empty-cart-block --></div>\n<!-- /wp:woocommerce/cart -->', 'Cart', '', 'publish', 'closed', 'closed', '', 'cart', '', '', '2024-09-09 11:34:22', '2024-09-09 11:34:22', '', 0, 'http://www.localhost/vivaio_wordpress/cart/', 0, 'page', '', 0),
