(38, 1, '2024-09-09 11:51:05', '2024-09-09 11:51:05', '<strong>Applications:</strong>\r\n<ul>\r\n 	<li>Indoor Remote Control of Security</li>\r\n 	<li>Intercom Systems</li>\r\n 	<li>Sound/ Audio Systems</li>\r\n 	<li>Door Controllers, Prox Sensors, Key Pads, Access Control, Smoke Detectors</li>\r\n 	<li>Indoor Applications</li>\r\n</ul>', 'Speaker/ Security Control', '', 'publish', 'closed', 'closed', '', 'speaker-security-control', '', '', '2024-09-09 12:19:37', '2024-09-09 12:19:37', '', 0, 'http://www.localhost/vivaio_wordpress/?post_type=product&#038;p=38', 0, 'product', '', 0),
