(45, 1, '2024-09-09 11:51:06', '2024-09-09 11:51:06', '<strong>Standard Compliance:</strong>\r\n<ul>\r\n 	<li>ISO/ IEC 11801</li>\r\n 	<li>ANSI/ TIA/ EIA 568-C.3</li>\r\n 	<li>IEC 61754</li>\r\n</ul>', 'Optical Fiber Adaptor', '', 'publish', 'closed', 'closed', '', 'optical-fiber-adaptor', '', '', '2024-09-09 12:11:26', '2024-09-09 12:11:26', '', 0, 'http://www.localhost/vivaio_wordpress/?post_type=product&#038;p=45', 0, 'product', '', 0),
(46, 1, '2024-09-09 11:51:06', '2024-09-09 11:51:06', 'VIVAIO Category 6 U/UTP cables are manufactured. Each cable consists of 8 color coded 24AWG polyethylene insulated conductors. These are twisted together to form 4 pairs with varying lay lengths. These pairs are then formed around a central ‘X’ shaped polyethylene filler. This filler assists in maintaining and enhancing the cables performance.', 'CAT6 Unshielded U/UTP Cable', '', 'publish', 'closed', 'closed', '', 'cat6-unshielded-u-utp-cable', '', '', '2024-09-09 12:10:59', '2024-09-09 12:10:59', '', 0, 'http://www.localhost/vivaio_wordpress/?post_type=product&#038;p=46', 0, 'product', '', 0),
(47, 1, '2024-09-09 11:51:06', '2024-09-09 11:51:06', '<table width=\"676\">\r\n<tbody>\r\n<tr>\r\n<td width=\"208\"><strong>Item</strong></td>\r\n<td width=\"467\"><strong>Standard</strong> <strong>Patch</strong> <strong>Cord</strong></td>\r\n</tr>\r\n<tr>\r\n<td rowspan=\"2\" width=\"208\"><strong>Cable</strong> <strong>Construction</strong></td>\r\n<td width=\"467\">U/UTP</td>\r\n</tr>\r\n<tr>\r\n<td width=\"467\">24AWG</td>\r\n</tr>\r\n<tr>\r\n<td width=\"208\"><strong>Standard</strong> <strong>Compliance</strong></td>\r\n<td width=\"467\">ISO/IEC 11801 ANSI/TIA-568.2-D IEC 61156-6</td>\r\n</tr>\r\n</tbody>\r\n</table>', 'CAT 6 PATCH CORD, UNSHIELDED', '', 'publish', 'closed', 'closed', '', 'cat-6-patch-cord-unshielded', '', '', '2024-09-09 12:10:13', '2024-09-09 12:10:13', '', 0, 'http://www.localhost/vivaio_wordpress/?post_type=product&#038;p=47', 0, 'product', '', 0),
