(51, 1, '2024-09-09 11:51:07', '2024-09-09 11:51:07', '<strong>Features &amp; Benefits:</strong>\r\n<ul>\r\n 	<li>Dust-proof shutter</li>\r\n 	<li>With label management</li>\r\n 	<li>Work with 86 back box</li>\r\n 	<li>Material: ABS</li>\r\n 	<li>Color: White</li>\r\n</ul>', '86 Faceplate And Back Box', '', 'publish', 'closed', 'closed', '', '86-faceplate-and-back-box', '', '', '2024-09-09 12:08:36', '2024-09-09 12:08:36', '', 0, 'http://www.localhost/vivaio_wordpress/?post_type=product&#038;p=51', 0, 'product', '', 0),
(52, 1, '2024-09-09 11:51:07', '2024-09-09 11:51:07', '<strong>Security &amp; Protection</strong>\r\n<ul>\r\n 	<li>Locking doors prevent unauthorized access to equipment.</li>\r\n 	<li>Two pairs of adjustable 19” EIA rails provide a stable mounting structure.</li>\r\n</ul>\r\n<strong>Flexibility</strong>\r\n<ul>\r\n 	<li>Vertical zero-U lacing panel pre- installed in rear corners for easy cable management</li>\r\n 	<li>Multiple cable entry options provide greater flexibility during installation.</li>\r\n 	<li>Removable and lockable half height side panels.</li>\r\n</ul>\r\n<strong>Multi-Use</strong>\r\n<ul>\r\n 	<li>Adaptable for use in data center build outs, computer rooms or data closets.</li>\r\n</ul>', 'Data Center Cabinet', '', 'publish', 'closed', 'closed', '', 'data-center-cabinet', '', '', '2024-09-09 12:08:13', '2024-09-09 12:08:13', '', 0, 'http://www.localhost/vivaio_wordpress/?post_type=product&#038;p=52', 0, 'product', '', 0),
(53, 1, '2024-09-09 11:51:07', '2024-09-09 11:51:07', '<strong>Security &amp; Protection</strong>\r\n<ul>\r\n 	<li>Locking doors prevent unauthorized access to equipment.</li>\r\n 	<li>SPCC (1mm) rails provide a stable mounting structure.</li>\r\n 	<li>Doors are grounded to the cabinet frame.</li>\r\n</ul>\r\n<strong>Flexibility</strong>\r\n<ul>\r\n 	<li>Multiple cable entry options provide greater flexibility during installation.</li>\r\n 	<li>Doors are removable for convenient access to equipment.</li>\r\n</ul>\r\n<strong>Multi-Use</strong>\r\n<ul>\r\n 	<li>Available in multiple sizes to fit in a variety of environments where space is limited.</li>\r\n 	<li>Adaptable for use in network, security and audio/video installations.</li>\r\n</ul>', 'Wall Cabinet (6U, 9U,10U,12U)', '', 'publish', 'closed', 'closed', '', 'wall-cabinet-6u-9u10u12u', '', '', '2024-09-09 12:07:52', '2024-09-09 12:07:52', '', 0, 'http://www.localhost/vivaio_wordpress/?post_type=product&#038;p=53', 0, 'product', '', 0),
